// Types for the Emscripten output of engine/wasm/bindings.cpp.
// connect4.js and connect4.wasm are generated by `pnpm build:wasm`; this file is hand-written.

export interface Connect4Module {
  /** View of the WASM heap. Re-read after every call: memory growth replaces it. */
  HEAP32: Int32Array;
  _malloc(bytes: number): number;
  _free(ptr: number): void;
  _c4_result_size(): number;
  _c4_reset(): void;
  _c4_choose_move(
    cellsPtr: number,
    player: number,
    depth: number,
    timeLimitMs: number,
    resultPtr: number
  ): number;
}

export default function createConnect4Module(overrides?: Record<string, unknown>): Promise<Connect4Module>;
